# test_matrix_transpose.py

import pytest

from your_module import matrix_transpose  # replace with the actual module name


@pytest.mark.parametrize(
    "matrix, expected",
    [
        (
            [[1, 2, 3], [4, 5, 6]],
            [[1, 4], [2, 5], [3, 6]],
        ),
        (
            [[1, 2], [3, 4]],
            [[1, 3], [2, 4]],
        ),
        (
            [[1, 2, 3]],
            [[1], [2], [3]],
        ),
        (
            [[1], [2], [3]],
            [[1, 2, 3]],
        ),
        (
            [["a", 1], [None, True]],
            [["a", None], [1, True]],
        ),
    ],
)
def test_matrix_transpose_happy_paths(matrix, expected):
    assert matrix_transpose(matrix) == expected


def test_matrix_transpose_empty_matrix():
    assert matrix_transpose([]) == []


@pytest.mark.parametrize(
    "matrix",
    [
        [[]],
        [[], []],
        [[], [], []],
    ],
)
def test_matrix_transpose_empty_rows(matrix):
    assert matrix_transpose(matrix) == []


def test_matrix_transpose_does_not_mutate_input():
    matrix = [[1, 2], [3, 4]]
    original = [row[:] for row in matrix]

    result = matrix_transpose(matrix)

    assert result == [[1, 3], [2, 4]]
    assert matrix == original


def test_matrix_transpose_ragged_matrix_with_shorter_later_row_raises_index_error():
    matrix = [[1, 2, 3], [4, 5]]

    with pytest.raises(IndexError):
        matrix_transpose(matrix)


def test_matrix_transpose_ragged_matrix_with_longer_later_row_ignores_extra_values():
    matrix = [[1], [2, 3]]

    assert matrix_transpose(matrix) == [[1, 2]]


def test_matrix_transpose_none_returns_empty_list():
    assert matrix_transpose(None) == []


@pytest.mark.parametrize(
    "invalid_matrix",
    [
        [1, 2, 3],
        ["abc", "def"],
    ],
)
def test_matrix_transpose_non_nested_iterables_raise_type_error(invalid_matrix):
    with pytest.raises(TypeError):
        matrix_transpose(invalid_matrix)


def test_matrix_transpose_scalar_input_raises_type_error():
    with pytest.raises(TypeError):
        matrix_transpose(42)
